// The human command catalog: the commands from commands.txt, as a C table.
//
// Generated by generator.cpp at build time; do not edit by hand, and do not commit
// a copy. It exists so `android-bin` resolves `argv[0]` (+ `argv[1]` subcommand) to
// the wire API name from the same list the symlinks are created from, with no second
// source of truth.
//
// `name` is what the operator types; `subcommand` is empty for a top-level command;
// `api` is the wire name the bridge serves.

#ifndef VYZORIX_ANDROID_BIN_COMMAND_CATALOG_H
#define VYZORIX_ANDROID_BIN_COMMAND_CATALOG_H

#include <cstddef>

struct CommandEntry {
    const char *name;
    const char *subcommand;
    const char *api;
};

extern const CommandEntry kCommands[];
extern const std::size_t kCommandCount;

/**
 * The wire API for `name` + `subcommand`, or nullptr when no command matches.
 *
 * `subcommand` may be nullptr, which matches only a top-level entry.
 */
const char *ResolveCommand(const char *name, const char *subcommand);

#endif // VYZORIX_ANDROID_BIN_COMMAND_CATALOG_H
